inline const char* get_note_name(const musical_note note, const bool prefer_flat = false)
{
    switch (note)
    {
        case musical_note::C: return musical_note_data::data::MUSICAL_NOTE_NAME_C;
		case musical_note::C_Sharp: return prefer_flat? musical_note_data::data::MUSICAL_NOTE_NAME_D_Flat : musical_note_data::data::MUSICAL_NOTE_NAME_C_Sharp;
		case musical_note::D: return musical_note_data::data::MUSICAL_NOTE_NAME_D;
		case musical_note::D_Sharp: return prefer_flat? musical_note_data::data::MUSICAL_NOTE_NAME_E_Flat : musical_note_data::data::MUSICAL_NOTE_NAME_D_Sharp;
		case musical_note::E: return musical_note_data::data::MUSICAL_NOTE_NAME_E;
		case musical_note::F: return musical_note_data::data::MUSICAL_NOTE_NAME_F;
		case musical_note::F_Sharp: return prefer_flat? musical_note_data::data::MUSICAL_NOTE_NAME_G_Flat : musical_note_data::data::MUSICAL_NOTE_NAME_F_Sharp;
		case musical_note::G: return musical_note_data::data::MUSICAL_NOTE_NAME_G;
		case musical_note::G_Sharp: return prefer_flat? musical_note_data::data::MUSICAL_NOTE_NAME_A_Flat : musical_note_data::data::MUSICAL_NOTE_NAME_G_Sharp;
		case musical_note::A: return musical_note_data::data::MUSICAL_NOTE_NAME_A;
		case musical_note::A_Sharp: return prefer_flat? musical_note_data::data::MUSICAL_NOTE_NAME_B_Flat : musical_note_data::data::MUSICAL_NOTE_NAME_A_Sharp;
		case musical_note::B: return musical_note_data::data::MUSICAL_NOTE_NAME_B;
        default: return musical_note_data::data::MUSICAL_NOTE_NAME_NONE;
    }
}

